values ('ap_statistics', 2, '2.11', array['2.11']::text[], 'list_sequence', 'Empirical rule (68–95–99.7 rule)', 'For a normal distribution, approximate percentages of observations lie within 1, 2, and 3 standard deviations of the mean.', '[{"label": "Within 1 SD of the mean", "meaning": "approximately 68%"}, {"label": "Within 2 SD of the mean", "meaning": "approximately 95%"}, {"label": "Within 3 SD of the mean", "meaning": "approximately 99.7%"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-statistics-reference-u2-u3-2026-10-10; candidate=ap_statistics-u2-r1-035; ced=2.11.C.1 "approximately 68% ... approximately 95% ... approximately 99.7%"')
